<script setup lang="ts">
import { computed, ref, onMounted } from 'vue'
import { request, query, session, type Page } from '../api'
import Modal from './Modal.vue'
import StatusBadge from './StatusBadge.vue'
const names:Record<string,string>={catalog:'船艇与商品资源',orders:'交易与合同',finance:'账本退款与提现',settings:'分红成长值配置',users:'账号历史与审计',organizations:'组织管理',applications:'入驻实名审核',customers:'客户管理',community:'资讯社区与活动核销',learning:'课程奖项',operations:'轮播与积分兑换',communication:'咨询预约与反馈',reports:'统计及Excel报表',rbac:'管理子角色配置'}
const rows=ref<any[]>([]),total=ref(0),page=ref(1),keys=ref<string[]>([]),orgs=ref<any[]>([]),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),editing=ref<any>(null),form=ref<any>({}),assigning=ref(false),accounts=ref<any[]>([]),search=ref(''),accountId=ref(''),assigned=ref<number[]>([]),selectedUser=ref<any>(null),assignLoading=ref(false)
const matchingRoles=computed(()=>rows.value.filter(role=>role.status==='active'&&role.base_role===selectedUser.value?.role&&String(role.org_id||'')===String(selectedUser.value?.org_id||'')))
async function load(){loading.value=true;error.value='';try{const [roles,permissions,organizations]=await Promise.all([request<Page>('/admin/roles'+query({page:page.value,page_size:100})),request<{items:string[]}>('/admin/permission-keys'),request<Page>('/admin/organizations?page_size=100')]);rows.value=roles.items;total.value=roles.total;keys.value=permissions.items.filter(key=>!session.user?.permissions||session.user.permissions.includes(key));orgs.value=organizations.items}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
function edit(row?:any){editing.value=row||{};form.value={name:row?.name||'',base_role:row?.base_role||'platform',org_id:row?.org_id||'',status:row?.status||'active',permissions:[...(row?.permissions||[])]};error.value=''}
async function save(){busy.value=true;error.value='';try{const body=editing.value.id?{name:form.value.name,status:form.value.status,permissions:form.value.permissions}:{name:form.value.name,base_role:form.value.base_role,org_id:form.value.base_role==='platform'?null:Number(form.value.org_id),permissions:form.value.permissions};await request('/admin/roles'+(editing.value.id?'/'+editing.value.id:''),{method:editing.value.id?'PATCH':'POST',body:JSON.stringify(body)});editing.value=null;success.value='管理子角色已保存';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
async function searchAccounts(){assignLoading.value=true;error.value='';try{const result=await request<Page>('/admin/users'+query({search:search.value,page_size:100}));accounts.value=result.items.filter(user=>['merchant','agency','platform'].includes(user.role)&&user.id!==session.user?.id)}catch(err){error.value=(err as Error).message}finally{assignLoading.value=false}}
async function selectAccount(){selectedUser.value=accounts.value.find(user=>String(user.id)===accountId.value)||null;assigned.value=[];if(!selectedUser.value)return;assignLoading.value=true;try{const result=await request<{role_ids:number[]}>(`/admin/users/${selectedUser.value.id}/roles`);assigned.value=result.role_ids.map(Number)}catch(err){error.value=(err as Error).message}finally{assignLoading.value=false}}
async function assign(){if(!selectedUser.value||busy.value)return;busy.value=true;error.value='';try{await request(`/admin/users/${selectedUser.value.id}/roles`,{method:'PUT',body:JSON.stringify({role_ids:assigned.value})});assigning.value=false;success.value='管理子角色已分配，权限由服务端实时核验'}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
function openAssignment(){assigning.value=true;search.value='';accountId.value='';selectedUser.value=null;assigned.value=[];error.value='';searchAccounts()}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>后台角色权限</h1><p>子角色收窄管理模块权限，身份与组织边界继续有效。</p></div><div class="recipient-row"><button class="button" @click="openAssignment">分配账号子角色</button><button class="button primary" @click="edit()">＋ 新增管理子角色</button></div></div><p v-if="error&&!editing&&!assigning" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><section class="panel"><div class="filter-bar"><span class="record-count">共 {{ total }} 个管理子角色</span><button class="text-button" @click="load">刷新</button></div><div class="table-scroll"><table><thead><tr><th>编号</th><th>名称</th><th>基础身份</th><th>所属机构</th><th>模块权限</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="7" class="empty">暂无管理子角色；未分配子角色的管理账号使用基础身份权限。</td></tr><tr v-for="row in rows" v-else :key="row.id"><td>#{{ row.id }}</td><td class="cell-title">{{ row.name }}</td><td>{{ {platform:'平台',merchant:'商家',agency:'经纪公司'}[row.base_role as 'platform'|'merchant'|'agency'] }}</td><td>{{ row.org_id?'机构 #'+row.org_id:'全平台身份' }}</td><td>{{ row.permissions.map((key:string)=>names[key]||key).join('、')||'无模块权限' }}</td><td><StatusBadge :value="row.status" /></td><td><button class="text-button" @click="edit(row)">编辑</button></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*100>=total||loading" @click="page++;load()">下一页</button></div></section><Modal v-if="editing" :title="editing.id?'编辑管理子角色':'新增管理子角色'" wide @close="!busy&&(editing=null)"><form id="role-edit" class="form-grid" @submit.prevent="save"><p v-if="error" class="notice danger span-all" role="alert">{{ error }}</p><label><span>角色名称 *</span><input v-model="form.name" required maxlength="100" /></label><label><span>基础身份</span><select v-model="form.base_role" :disabled="!!editing.id" @change="form.org_id=''"><option value="platform">平台</option><option value="merchant">商家</option><option value="agency">经纪公司</option></select></label><label v-if="form.base_role!=='platform'"><span>对应机构 *</span><select v-model="form.org_id" required :disabled="!!editing.id"><option value="">请选择</option><option v-for="org in orgs.filter(row=>row.status==='approved'&&row.kind===form.base_role)" :key="org.id" :value="org.id">{{ org.name }} #{{ org.id }}</option></select></label><label v-if="editing.id"><span>角色状态</span><select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="span-all"><h3>允许访问的模块</h3><div class="checkbox-grid"><label v-for="key in keys" :key="key"><input v-model="form.permissions" type="checkbox" :value="key" /><span>{{ names[key]||key }}</span></label></div><p class="muted">基础身份和机构创建后不可修改；只能授权当前操作者已有的模块。</p></div></form><template #footer><button class="button" :disabled="busy" @click="editing=null">取消</button><button class="button primary" form="role-edit" :disabled="busy">{{ busy?'正在保存…':'保存子角色' }}</button></template></Modal><Modal v-if="assigning" title="分配账号子角色" wide @close="!busy&&(assigning=false)"><form id="role-assign" class="form-grid" @submit.prevent="assign"><p v-if="error" class="notice danger span-all" role="alert">{{ error }}</p><div class="recipient-row span-all"><input v-model="search" aria-label="搜索管理账号" placeholder="账号或姓名" /><button type="button" class="button" :disabled="assignLoading" @click="searchAccounts">查询账号</button></div><label class="span-all"><span>管理账号 *</span><select v-model="accountId" aria-label="管理账号" required :disabled="assignLoading" @change="selectAccount"><option value="">请选择</option><option v-for="user in accounts" :key="user.id" :value="String(user.id)">{{ user.nickname||user.username }} · {{ user.role }} · 机构 #{{ user.org_id||'—' }}</option></select></label><div v-if="selectedUser" class="span-all"><h3>同身份、同机构的启用子角色</h3><p v-if="!matchingRoles.length" class="notice">当前没有匹配角色，请先创建同身份同机构的角色。</p><div class="checkbox-grid"><label v-for="role in matchingRoles" :key="role.id"><input v-model="assigned" :disabled="assignLoading" type="checkbox" :value="Number(role.id)" /><span>{{ role.name }}</span></label></div><p class="notice warning">清空分配将恢复基础身份的管理模块权限，仅拥有全部模块权限的平台账号可以执行。不能修改自身权限。</p></div></form><template #footer><button class="button" :disabled="busy" @click="assigning=false">取消</button><button class="button primary" form="role-assign" :disabled="busy||assignLoading||!selectedUser">{{ busy?'正在分配…':'保存账号权限' }}</button></template></Modal></template>
